mapper.select:
SELECT *
FROM training_video
WHERE is_active = 1

    AND main_category = #{category}

ORDER BY view_count DESC, like_count DESC
LIMIT #{limit}

mapper.sql:
FROM training_video
WHERE is_active = 1

    AND main_category = #{category}


    AND level = #{level}



    AND duration_sec <= 900

mapper.select:
SELECT 1
FROM training_video_like
WHERE user_id = #{userId}
AND video_id = #{videoId}
LIMIT 1

mapper.delete:
DELETE FROM training_video_like
WHERE user_id = #{userId}
AND video_id = #{videoId}

mapper.update:
UPDATE training_video
SET like_count = like_count + 1
WHERE id = #{id}

UPDATE training_video
SET like_count = like_count - 1
WHERE id = #{id}
